import { useEffect, useState } from 'react';

function Title() {
  const [count, setCount] = useState(0);

  useEffect(() => {
    document.title = `${count} new messages`;
  }, [count]);

  return <button onClick={() => setCount(count + 1)}>Add message</button>;
}

import { useEffect } from 'react';

function Logger({ userId }) {
  useEffect(() => {
    console.log('after every render');
  });

  useEffect(() => {
    console.log('once after mount');
  }, []);

  useEffect(() => {
    console.log('userId is now', userId);
  }, [userId]);

  return <p>User {userId}</p>;
}

import { useEffect, useState } from 'react';

function Clock() {
  const [seconds, setSeconds] = useState(0);

  useEffect(() => {
    const id = setInterval(() => setSeconds((s) => s + 1), 1000);
    return () => clearInterval(id);
  }, []);

  return <p>Running for {seconds} s</p>;
}

import { useEffect, useState } from 'react';

function UserList() {
  const [users, setUsers] = useState([]);
  const [status, setStatus] = useState('loading');

  useEffect(() => {
    let ignore = false;

    fetch('https://jsonplaceholder.typicode.com/users?_limit=3')
      .then((res) => {
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        return res.json();
      })
      .then((data) => {
        if (!ignore) {
          setUsers(data);
          setStatus('ready');
        }
      })
      .catch(() => {
        if (!ignore) setStatus('error');
      });

    return () => {
      ignore = true;
    };
  }, []);

  if (status === 'loading') return <p>Loading…</p>;
  if (status === 'error') return <p>Could not load users.</p>;

  return (
    <ul>
      {users.map((user) => (
        <li key={user.id}>{user.name}</li>
      ))}
    </ul>
  );
}
